"""Original MathMagic narration and animation storyboard. Fractions stay structured."""

def F(n, d): return [n, d]
def M(w, n, d): return [w, n, d]
def row(n, d, label='', colour='teal'): return dict(n=n, d=d, label=label, colour=colour)
def beat(text, chapter, eq=None, rows=None, note='', line=None, area=None, context=None):
    return dict(text=text, chapter=chapter, equation=eq or [], rows=rows or [],
                note=note, line=line, area=area, context=context)
def line(d, points, maximum=1, jump=None):
    return dict(d=d, points=points, maximum=maximum, jump=jump)

