beat('So one third is greater than one sixth. A bigger denominator does not always mean a bigger fraction.', 'Unit fractions', [F(1,3),'>',F(1,6)], [row(1,3,'One third'),row(1,6,'One sixth','gold')], note='For unit fractions, compare the size of one piece.'),
